const steps={web:['Enter the page information, rules or URLs you control.','Generate the file or markup and review its content.','Copy or download it for use on your own website.'],images:['Choose a clear, supported image from your device.','Adjust the image settings and run the tool.','Inspect the preview, then download or copy the result.'],creators:['Choose your image or enter your own text.','Pick a layout, style or output size.','Create the result and download your shareable image.'],calculators:['Enter the numbers, dates or units you want to compare.','Choose the calculation options and calculate.','Review the result together with the assumptions shown.'],study:['Choose a study tool and review its input labels.','Enter your scores, course details, passage or available study time.','Run the tool and review the result and its assumptions.'],text:['Type or paste the text you want to work with.','Choose a conversion, clean-up or output option.','Copy the result or download it when an export is available.'],developer:['Enter a sample value, color, URL or structured input.','Choose the required format or options and run the tool.','Review the output and copy it into your own workflow.'],pdf:['Choose the PDF documents or images from your device.','Arrange files or enter the pages and layout options.','Create the document and download the finished PDF.'],everyday:['Choose or enter the content for this tool.','Start the action with the settings you want.','Review the result before copying, sharing or continuing.']};
export function toolInfo(t){const d=details[t.id];if(!d)throw Error('Missing editorial content for '+t.id);const p=priorityTools[t.id];return {purpose:p?.purpose||d[0],example:p?.example||d[1],tip:p?.tip||d[2],steps:p?.steps||latestSteps[t.id]||steps[t.category]||['Enter your own values or choose a supported file.','Adjust the options and run the tool.','Review the result, then copy, export or save it when available.']};}
export function guideHTML(t){const d=toolInfo(t);return `<article class="tool-guide" aria-label="${e(t.title)} guide"><div class="guide-columns"><section><span class="eyebrow">A useful little guide</span><h2>How to use ${e(t.title.toLowerCase())}</h2><p>${e(d.purpose)}</p><ol>${d.steps.map(s=>`<li>${e(s)}</li>`).join('')}</ol></section><section class="example-card"><span class="status-pill">A real use case</span><h3>Try this next</h3><p>${e(d.example)}</p><div class="example-tip"><strong>A detail to keep in mind</strong><p>${e(d.tip)}</p></div></section></div><p class="text-version"><a href="./tools/${e(t.id)}/index.md" type="text/markdown">Read these instructions as plain text ↗</a></p>${priorityHTML(t.id,e)}${searchQuestionsHTML(t.id,e)}<div class="tool-faq"><h2>Questions, answered.</h2><details><summary>Is ${e(t.title.toLowerCase())} free to use?</summary><p>Yes. This tool is part of Nepocore’s free browser toolkit. There is no paid tier, file-download gate or application account required.</p></details><details><summary>What should I check before using the result?</summary><p>${e(d.tip)}</p></details><details><summary>Does this tool upload my files or text?</summary><p>${t.id==='text-to-speech'?'Your browser or operating system provides the voice. Device voices can work locally; online system voices may send the text to their speech provider. Nepocore does not receive the text.':'The tool processes its input in your browser. '+(['image-to-text','background-remover'].includes(t.id)?'Its engine or model may download from a third-party CDN on first use, but your image is processed on your device.':'File contents and text are not sent to a processing server.')} See the <a href="./privacy/">privacy page</a> for local storage and hosting details.</p></details></div>${collectionSources[t.id]?`<aside class="method-sources"><h3>Method & sources</h3><ul>${collectionSources[t.id].map(([label,url])=>`<li><a href="${e(url)}" target="_blank" rel="noopener noreferrer">${e(label)} ↗</a></li>`).join('')}</ul>${['health','pregnancy'].includes(t.category)?'<p>Informational calculations and logs. No clinical review or individual diagnosis is claimed.</p>':''}</aside>`:''}</article>`;}
export function pagePath(type,id){return type==='home'?'':type==='tool'?`tools/${id}/`:type==='category'?`categories/${id}/`:type==='catalog'?'tools/':type==='article'?`blog/${id}/`:type==='blogCategory'?`blog/category/${id}/`:`${type}/`;}
export function seoMeta(type,id){const t=tools.find(x=>x.id===id),c=categories.find(x=>x.id===id);let title,description;if(type==='article'){const p=blogIndex.find(p=>p.slug===id);title=p.title+' | Nepocore Guides';description=p.summary;}else if(type==='blog'||type==='blogCategory'){title=(type==='blog'?'Practical Tool Guides':(blogCategories.find(c=>c[0]===id)?.[1]||'Practical')+' Guides')+' | Nepocore';description=type==='blogCategory'?({images:'Practical image guides for JPEG, PNG, WebP, resizing, compression and background removal, with worked examples and links to free browser tools.',creative:'Learn to make memes, screenshot frames, quote cards and social graphics with clear examples and free Nepocore creator tools.',documents:'Step-by-step guides for merging, splitting and exporting PDFs, plus QR code design, scanning and print preparation.',learning:'Practical study guides for IELTS band calculations, typing practice, flashcards and printable worksheets with free learning tools.',planning:'Worked examples for dates, time zones, everyday planning and household calculations, with clear assumptions and browser tools.',security:'Guides to strong passwords, hashes, encodings and developer utilities, including privacy limits and primary technical references.',money:'Understand unit prices, discounts, loan repayments and money arithmetic using worked examples and free calculators.',business:'Practical guides for invoices, price calculations, inventory and small business records, with templates and free browser tools.',nepal:'Nepal-focused guides for Unicode typing, calendar conversion, local units and useful everyday calculations.'}[id]||'Practical '+(blogCategories.find(c=>c[0]===id)?.[1]||'tool')+' guides, examples and related browser tools.'): 'Original practical guides with worked examples, clear steps and tool links for images, PDFs, planning, learning, security, money and Nepal.';}else if(type==='tool'&&t){title=`Free ${t.title} Online | Nepocore`;description=toolInfo(t).purpose;}else if(type==='category'&&c){title=`Free ${c.name} Online | Nepocore`;description=`Explore free ${c.name.toLowerCase()} on Nepocore. Find useful browser tools, clear examples and local processing for your everyday tasks.`;}else if(type==='home'){title=`Nepocore — ${tools.length} Free Online Tools for Everyday Tasks`;description='Free image converters, background removal, OCR, meme maker, IELTS calculators, PDFs, QR tools and more. Create and calculate in your browser with Nepocore.';}else if(type==='catalog'){title=`All ${tools.length} Free Online Tools — Browse the Toolkit | Nepocore`;description=`Browse ${tools.length} free tools for photos, health, pregnancy, sports, study, Nepal, audio, business, developers and everyday tasks. Search by task and find your next shortcut.`;}else{const names={sites:'Nepocore Websites & Projects',resources:'Free Math Worksheets & Answer Keys',about:'About Nepocore',privacy:'Privacy Policy',terms:'Terms of Use',faq:'Frequently Asked Questions',contact:'Contact Nepocore',favorites:'My Favorite Tools',notfound:'Page Not Found',cookies:'Cookie & Storage Policy',disclaimer:'Tool & Content Disclaimer','editorial-policy':'Editorial & Corrections Policy',accessibility:'Accessibility Statement',security:'Application Security','advertising-policy':'Advertising Policy'};title=(names[type]||'Nepocore')+' | Nepocore';description=type==='sites'?'Find every official Nepocore website: the main tools collection, the dedicated resume builder and nine planned projects, with clear availability information.':type==='about'?'Learn about Nepocore Tools at nepocore.com: free browser calculators, image and PDF tools, study utilities and printable worksheets.':type==='resources'?'Download three free A4 math practice worksheets with separate answer keys. Read all questions as HTML or create custom printable worksheets in Nepocore.':type==='privacy'?'Learn how Nepocore processes files locally, stores preferences and loads optional model assets.':type==='faq'?'Answers about free tools, local file processing, image formats, OCR, IELTS scoring, PDF limits and hosting.':`Read ${names[type]||'more about Nepocore'}, a free collection of useful tools for daily work and creativity.`;}
 if(type==='tool'&&searchIntents[id])({title,description}=searchIntents[id]);
 return {title,description:description.length>159?description.slice(0,156).replace(/\s+\S*$/,'')+'…':description,path:pagePath(type,id),noindex:['favorites','notfound'].includes(type)};
}
export function schemaData(page,root){const base=new URL(root),meta=seoMeta(page.type,page.id),url=new URL(meta.path,base).href,identityPage=['home','about','sites'].includes(page.type),identityDescription='Nepocore is a free online tools website for browser-based calculators, image and PDF tools, study utilities and printable worksheets.',graph=[{'@type':'WebSite','@id':new URL('#website',base).href,name:'Nepocore',url:base.href,inLanguage:'en',...(identityPage?{hasPart:networkSites.filter(s=>s.status==='live'&&s.id!=='tools').map(s=>({'@type':'WebSite','@id':s.url+'#website',name:s.name,url:s.url,description:s.description,publisher:{'@id':new URL('#organization',base).href}}))}:{}),...(identityPage?{alternateName:['Nepocore Tools',base.hostname],description:identityDescription,publisher:{'@id':new URL('#organization',base).href}}:{})},{'@type':'Organization','@id':new URL('#organization',base).href,name:'Nepocore',url:base.href,logo:new URL('assets/icon-512.png',base).href,...(identityPage?{alternateName:'Nepocore Tools',description:identityDescription}:{})}];if(['blog','blogCategory','article'].includes(page.type))graph.push(...blogSchema(page,root));else if(page.type==='tool'){const t=tools.find(t=>t.id===page.id),c=categories.find(c=>c.id===t.category);graph.push({'@type':'WebApplication',name:t.title,url,image:socialMeta(meta.path,meta.title,base).image,description:toolInfo(t).purpose,operatingSystem:'Any modern browser',applicationCategory:['creators','images','pdf','fun','audio'].includes(t.category)?'MultimediaApplication':['health','pregnancy'].includes(t.category)?'HealthApplication':['gaming'].includes(t.category)?'GameApplication':t.category==='education'||t.category==='study'?'EducationalApplication':'UtilitiesApplication',browserRequirements:'Requires a modern browser with JavaScript enabled',isAccessibleForFree:true,offers:{'@type':'Offer',price:'0',priceCurrency:'USD'}},{'@type':'BreadcrumbList',itemListElement:[{'@type':'ListItem',position:1,name:'Home',item:base.href},{'@type':'ListItem',position:2,name:c.name,item:new URL(pagePath('category',c.id),base).href},{'@type':'ListItem',position:3,name:t.title,item:url}]});}else if(page.type==='sites'){graph.push({'@type':'CollectionPage',name:meta.title,url,description:meta.description,mainEntity:{'@type':'ItemList',name:'Official Nepocore websites and planned projects',numberOfItems:networkSites.length,itemListElement:networkSites.map((s,i)=>({'@type':'ListItem',position:i+1,name:s.name,url:s.url,description:(s.status==='live'?'Available now. ':'Planned; not yet launched. ')+s.description}))}});}else if(['home','catalog','category'].includes(page.type)){const list=tools.filter(t=>page.type!=='category'||t.category===page.id);graph.push({'@type':'CollectionPage',name:meta.title,url,description:meta.description,mainEntity:{'@type':'ItemList',numberOfItems:list.length,itemListElement:list.map((t,i)=>({'@type':'ListItem',position:i+1,name:t.title,url:preferredToolURL(t.id)||new URL(pagePath('tool',t.id),base).href}))}});}else graph.push({'@type':'WebPage',name:meta.title,url,description:meta.description});return {'@context':'https://schema.org','@graph':graph};}
